SELECT msi.server_name FROM map_server_info msi where msi.pulished_proctol ~* #{serviceName} and msi.server_show = 0 AND msi.server_status != 0 AND (msi.is_public = 1
OR msi.server_token = #{token}
)

SELECT msi.server_name as layerName, msi.file_type as fileType, msi.description as description, msi.is_layer_group as isLayerGroup, mfi.resource_crs as resourceSrs, mfi.native_crs as nativeSrs, mfi.resource_bbox as resourceBbox, mfi.native_bbox as nativaBbox, si.style_name as styleName FROM map_server_info msi left join map_feature_info mfi on msi.server_id = mfi.server_id left join server_style_info ssi on msi.server_id=ssi.server_id left join style_info si on ssi.style_id = si.id where msi.pulished_proctol ~* #{serviceName} AND msi.server_status != 0 AND msi.server_show = 0 AND (msi.is_public = 1
OR msi.server_token = #{token}
)
